  const now = ctx.clock.now().getTime();
  return ctx.store.invoices
    .find((i) => i.status === 'open' && new Date(i.dueAt).getTime() < now)
    .sort((a, b) => new Date(a.dueAt).getTime() - new Date(b.dueAt).getTime())
